# Extract IQ lookup tables from llama.cpp ggml-common.h into Rust.
# Usage: python -I tools/gen_tables.py ~/Clones/llama.cpp/ggml/src/ggml-common.h > src/quant/tables.rs
import re
import sys

src = open(sys.argv[1]).read()


def arr(name):
    m = re.search(
        r"GGML_TABLE_BEGIN\(\w+,\s*" + name + r",\s*\d+\)(.*?)GGML_TABLE_END", src, re.S
    )
    body = re.sub(r"//.*", "", m.group(1))
    vals = [
        x.strip()
        for x in body.replace("{", " ").replace("}", " ").split(",")
        if x.strip()
    ]
    return [
        re.sub(r"(?i)(ull|ul|u)$", "", v)
        if v.lower().startswith("0x") or v.isdigit()
        else v
        for v in vals
    ]


spec = [
    ("iq2xs_grid", "IQ2XS_GRID", "u64"),
    ("iq3xxs_grid", "IQ3XXS_GRID", "u32"),
    ("ksigns_iq2xs", "KSIGNS_IQ2XS", "u8"),
    ("kmask_iq2xs", "KMASK_IQ2XS", "u8"),
    ("kvalues_iq4nl", "KVALUES_IQ4NL", "i8"),
]
print(
    "// Generated by tools/gen_tables.py from llama.cpp ggml-common.h (MIT License, ggml authors). Do not edit."
)
print("#![cfg_attr(rustfmt, rustfmt_skip)]")
for c, r, t in spec:
    v = arr(c)
    print(f"pub static {r}: [{t}; {len(v)}] = [{', '.join(v)}];")
